INSERT INTO public.quiz_questions
  (slug, tier, module, body, difficulty, question, options, answer, explanation, reference, is_published)
VALUES
  ('mdf-art-001', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «يطلق على هذا القانون اسم مدونة الأسرة، ويشار إليها بعده باسم المدونة»؟', '["المادة 1", "المادة 2", "المادة 3", "المادة 4"]'::jsonb, 0, 'المادة 1 من مدونة الأسرة تنص على: «يطلق على هذا القانون اسم مدونة الأسرة، ويشار إليها بعده باسم المدونة.»', 'مدونة الأسرة، المادة 1', true),
  ('mdf-art-002', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «تسري أحكام هذه المدونة على: 1 - جميع المغاربة ولو كانوا حاملين لجنسية أخرى؛ 2 - اللاجئين بمن فيهم عديمو الجنسية، طبقا لاتفاقية جنيف المؤرخة ب 28 يوليوز لسنة 1951 المتعلقة بوضعية اللاجئين؛ 3 - العلاقات التي يكون فيها أحد الطرفين مغربيا؛ 4- العلاقات التي تكون»؟', '["المادة 1", "المادة 2", "المادة 3", "المادة 4"]'::jsonb, 1, 'المادة 2 من مدونة الأسرة تنص على: «تسري أحكام هذه المدونة على: 1 - جميع المغاربة ولو كانوا حاملين لجنسية أخرى؛ 2 - اللاجئين بمن فيهم عديمو الجنسية، طبقا لاتفاقية جنيف المؤرخة ب 28 يوليوز لسنة 1951 المتعلقة بوضعية اللاجئين؛ 3 - العلاقات التي يكون فيها أحد الطرفين مغربيا؛ 4- العلاقات التي تكون بين مغربيين أحدهما مسلم. أما اليهود المغاربة فتسري عليهم قواعد الأحوال الشخصية العبرية المغربية.»', 'مدونة الأسرة، المادة 2', true),
  ('mdf-art-003', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «تعتبر النيابة العامة طرفا أصليا في جميع القضايا الرامية إلى تطبيق أحكام هذه المدونة»؟', '["المادة 2", "المادة 3", "المادة 4", "المادة 5"]'::jsonb, 1, 'المادة 3 من مدونة الأسرة تنص على: «تعتبر النيابة العامة طرفا أصليا في جميع القضايا الرامية إلى تطبيق أحكام هذه المدونة. الكتاب الأول: الزواج القسم الأول: الخطبة والزواج»', 'مدونة الأسرة، المادة 3', true),
  ('mdf-art-004', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «الزواج ميثاق تراض وترابط شرعي بين رجل وامرأة على وجه الدوام، غايته الإحصان والعفاف وإنشاء أسرة مستقرة، برعاية الزوجين طبقا لأحكام هذه المدونة»؟', '["المادة 3", "المادة 4", "المادة 5", "المادة 6"]'::jsonb, 1, 'المادة 4 من مدونة الأسرة تنص على: «الزواج ميثاق تراض وترابط شرعي بين رجل وامرأة على وجه الدوام، غايته الإحصان والعفاف وإنشاء أسرة مستقرة، برعاية الزوجين طبقا لأحكام هذه المدونة. الباب الأول: الخطبة»', 'مدونة الأسرة، المادة 4', true),
  ('mdf-art-005', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «الخطبة تواعد رجل وامرأة على الزواج. تتحقق الخطبة بتعبير طرفيها بأي وسيلة متعارف عليها تفيد التواعد على الزواج، ويدخل في حكمها قراءة الفاتحة وما جرت به العادة والعرف من تبادل الهدايا»؟', '["المادة 4", "المادة 5", "المادة 6", "المادة 7"]'::jsonb, 1, 'المادة 5 من مدونة الأسرة تنص على: «الخطبة تواعد رجل وامرأة على الزواج. تتحقق الخطبة بتعبير طرفيها بأي وسيلة متعارف عليها تفيد التواعد على الزواج، ويدخل في حكمها قراءة الفاتحة وما جرت به العادة والعرف من تبادل الهدايا.»', 'مدونة الأسرة، المادة 5', true),
  ('mdf-art-006', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «يعتبر الطرفان في فترة خطبة إلى حين الإشهاد على عقد الزواج، ولكل من الطرفين حق العدول عنها»؟', '["المادة 5", "المادة 6", "المادة 7", "المادة 8"]'::jsonb, 1, 'المادة 6 من مدونة الأسرة تنص على: «يعتبر الطرفان في فترة خطبة إلى حين الإشهاد على عقد الزواج، ولكل من الطرفين حق العدول عنها.»', 'مدونة الأسرة، المادة 6', true),
  ('mdf-art-007', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «مجرد العدول عن الخطبة لا يترتب عنه تعويض»؟', '["المادة 6", "المادة 7", "المادة 8", "المادة 9"]'::jsonb, 1, 'المادة 7 من مدونة الأسرة تنص على: «مجرد العدول عن الخطبة لا يترتب عنه تعويض. غير أنه إذا صدر عن أحد الطرفين فعل سبب ضررا للآخر، يمكن للمتضرر المطالبة بالتعويض.»', 'مدونة الأسرة، المادة 7', true),
  ('mdf-art-008', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «لكل من الخاطب والمخطوبة أن يسترد ما قدمه من هدايا، ما لم يكن العدول عن الخطبة من قبله»؟', '["المادة 7", "المادة 8", "المادة 9", "المادة 10"]'::jsonb, 1, 'المادة 8 من مدونة الأسرة تنص على: «لكل من الخاطب والمخطوبة أن يسترد ما قدمه من هدايا، ما لم يكن العدول عن الخطبة من قبله. ترد الهدايا بعينها، أو بقيمتها حسب الأحوال.»', 'مدونة الأسرة، المادة 8', true),
  ('mdf-art-009', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «إذا قدم الخاطب الصداق أو جزءا منه، وحدث عدول عن الخطبة أو مات أحد الطرفين أثناءها، فللخاطب أو لورثته استرداد ما سلم بعينه إن كان قائما، وإلا فمثله أو قيمته يوم تسلمه»؟', '["المادة 8", "المادة 9", "المادة 10", "المادة 11"]'::jsonb, 1, 'المادة 9 من مدونة الأسرة تنص على: «إذا قدم الخاطب الصداق أو جزءا منه، وحدث عدول عن الخطبة أو مات أحد الطرفين أثناءها، فللخاطب أو لورثته استرداد ما سلم بعينه إن كان قائما، وإلا فمثله أو قيمته يوم تسلمه. إذا لم ترغب المخطوبة في أداء المبلغ الذي تحول إلى جهاز، يتحمل المتسبب في العدول ما قد ينتج عن ذلك من خسارة بين قيمة الجهاز والمبلغ المدفوع فيه. الباب الثاني: الزواج»', 'مدونة الأسرة، المادة 9', true),
  ('mdf-art-010', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «ينعقد الزواج بإيجاب من أحد المتعاقدين وقبول من الآخر، بألفاظ تفيد معنى الزواج لغة أو عرفا»؟', '["المادة 9", "المادة 10", "المادة 11", "المادة 12"]'::jsonb, 1, 'المادة 10 من مدونة الأسرة تنص على: «ينعقد الزواج بإيجاب من أحد المتعاقدين وقبول من الآخر، بألفاظ تفيد معنى الزواج لغة أو عرفا. يصح الإيجاب والقبول من العاجز عن النطق بالكتابة إن كان يكتب، وإلا فبإشارته المفهومة من الطرف الآخر ومن الشاهدين.»', 'مدونة الأسرة، المادة 10', true),
  ('mdf-art-011', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «يشترط في الإيجاب والقبول أن يكونا: 1 - شفويين عند الاستطاعة، وإلا فبالكتابة أو الإشارة المفهومة؛ 2- متطابقين وفي مجلس واحد؛ 63 - باتين غير مقيدين بأجل أو شرط واقف أو فاسخ»؟', '["المادة 10", "المادة 11", "المادة 12", "المادة 13"]'::jsonb, 1, 'المادة 11 من مدونة الأسرة تنص على: «يشترط في الإيجاب والقبول أن يكونا: 1 - شفويين عند الاستطاعة، وإلا فبالكتابة أو الإشارة المفهومة؛ 2- متطابقين وفي مجلس واحد؛ 63 - باتين غير مقيدين بأجل أو شرط واقف أو فاسخ.»', 'مدونة الأسرة، المادة 11', true),
  ('mdf-art-012', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «تطبق على عقد الزواج المشوب بإكراه أو تدليس الأحكام المنصوص عليها في المادتين 3 و66 بعده»؟', '["المادة 11", "المادة 12", "المادة 13", "المادة 14"]'::jsonb, 1, 'المادة 12 من مدونة الأسرة تنص على: «تطبق على عقد الزواج المشوب بإكراه أو تدليس الأحكام المنصوص عليها في المادتين 3 و66 بعده.»', 'مدونة الأسرة، المادة 12', true),
  ('mdf-art-013', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «يجب أن تتوفر في عقد الزواج الشروط الآتية: 1 - أهلية الزوج والزوجة؛ 2 - عدم الاتفاق على إسقاط الصداق؛ 3 - ولي الزواج عند الاقتضاء؛ 4- سماع العدلين التصريح بالإيجاب والقبول من الزوجين وتوثيقه؛ 5 - انتفاء الموانع الشرعية»؟', '["المادة 12", "المادة 13", "المادة 14", "المادة 15"]'::jsonb, 1, 'المادة 13 من مدونة الأسرة تنص على: «يجب أن تتوفر في عقد الزواج الشروط الآتية: 1 - أهلية الزوج والزوجة؛ 2 - عدم الاتفاق على إسقاط الصداق؛ 3 - ولي الزواج عند الاقتضاء؛ 4- سماع العدلين التصريح بالإيجاب والقبول من الزوجين وتوثيقه؛ 5 - انتفاء الموانع الشرعية.»', 'مدونة الأسرة، المادة 13', true),
  ('mdf-art-014', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «يمكن للمغاربة المقيمين في الخارج، أن يبرموا عقود زواجهم وفقا للإجراءات الإدارية المحلية لبلد إقامتهم، إذا توفر الإيجاب والقبول والأهلية والولي عند الاقتضاء، وانتفت الموانع ولم ينص على إسقاط الصداق، وحضره شاهدان مسلمان، مع مراعاة أحكام المادة 21 بعده»؟', '["المادة 13", "المادة 14", "المادة 15", "المادة 16"]'::jsonb, 1, 'المادة 14 من مدونة الأسرة تنص على: «يمكن للمغاربة المقيمين في الخارج، أن يبرموا عقود زواجهم وفقا للإجراءات الإدارية المحلية لبلد إقامتهم، إذا توفر الإيجاب والقبول والأهلية والولي عند الاقتضاء، وانتفت الموانع ولم ينص على إسقاط الصداق، وحضره شاهدان مسلمان، مع مراعاة أحكام المادة 21 بعده.»', 'مدونة الأسرة، المادة 14', true),
  ('mdf-art-015', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «يجب على المغاربة الذين أبرموا عقد الزواج طبقا للقانون المحلي لبلد إقامتهم، أن يودعوا نسخة منه داخل أجل ثلاثة أشهر من تاريخ إبرامه، بالمصالح القنصلية المغربية التابعة لها محل سكنى طالبة أو طالب التسجيل أو محل إبرام العقد»؟', '["المادة 14", "المادة 15", "المادة 16", "المادة 17"]'::jsonb, 1, 'المادة 15 من مدونة الأسرة تنص على: «يجب على المغاربة الذين أبرموا عقد الزواج طبقا للقانون المحلي لبلد إقامتهم، أن يودعوا نسخة منه داخل أجل ثلاثة أشهر من تاريخ إبرامه، بالمصالح القنصلية المغربية التابعة لها محل سكنى طالبة أو طالب التسجيل أو محل إبرام العقد. تسري أحكام الفقرة الأولى أعلاه أيضا على عقود الزواج المبرمة، من طرف المغاربة حسب القانون المحلي لبلدان الإقامة، قبل تاريخ نشر هذا القانون بالجريدة الرسمية. إذا لم توجد هذه المصالح، ترسل النسخة داخل نفس الأجل إلى الوزارة المكلفة بالشؤون الخارجية. تتولى هذه الأخيرة إرسال النسخة المذكورة إلى ضابط الحالة المدنية وإلى قسم قضاء الأسرة لمحل ولادة كل من الزوجين. إذا لم يكن للزوجين أو لأحدهما محل ولادة بالمغرب، فإن النسخة توجه إلى قسم قضاء الأسرة بالرباط وإلى وكيل الملك بالمحكمة الابتدائية بالرباط. 2 - تم تغيير وتتميم الفقرة الأولى من المادة 15 أعلاه، بمقتضى المادة الفريدة من القانون رقم 65.21 القاضي بتغيير وتتميم المادة 15 من القانون رقم 70.03 بمثابة مدونة الأسرة، الصادر بتنفيذه الظهير الشريف رقم 1.21.73 بتاريخ 3 ذي الحجة 1442 (14 يوليو 2021)، الجريدة الرسمية عدد 7008 بتاريخ 18 ذو الحجة 1442 (29 يوليو 2021)، ص 5774. 3- بمقتضى القانون رقم 70.03 بمثابة مدونة الأسرة، الصادر بتنفيذه الظهير الشريف رقم 1.04.22 بتاريخ 12 من ذي الحجة 1424 (3 فبراير 2004): تنص الفقرة الرابعة من المادة 16 منه على ما يلي: "يعمل بسماع دعوى الزوجية في فترة انتقالية لا تتعدى خمس سنوات، ابتداء من تاريخ دخول هذا القانون حيز التنفيذ". ه وقد تم تعديل الفقرة الرابعة من المادة 16 أعلاه، كالآتي:»', 'مدونة الأسرة، المادة 15', true),
  ('mdf-art-016', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «تعتبر وثيقة عقد الزواج الوسيلة المقبولة لإثبات الزواج»؟', '["المادة 15", "المادة 16", "المادة 17", "المادة 18"]'::jsonb, 1, 'المادة 16 من مدونة الأسرة تنص على: «تعتبر وثيقة عقد الزواج الوسيلة المقبولة لإثبات الزواج. إذا حالت أسباب قاهرة دون توثيق العقد في وقته، تعتمد المحكمة في سماع دعوى الزوجية سائر وسائل الإثبات و كذا الخبرة. تأخذ المحكمة بعين الاعتبار وهي تنظر في دعوى الزوجية وجود أطفال أو حمل ناتج عن العلاقة الزوجية، وما إذا رفعت الدعوى في حياة الزوجين. يعمل بسماع دعوى الزوجية في فترة انتقالية لا تتعدى خمسة عشر سنة ابتداء من تاريخ دخول هذا القانون حيز التنفيذ.³»', 'مدونة الأسرة، المادة 16', true),
  ('mdf-art-017', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «يتم عقد الزواج بحضور أطرافه، غير أنه يمكن التوكيل على إبرامه، بإذن من قاضي الأسرة، المكلف بالزواج وفق الشروط الآتية: 1 - وجود ظروف خاصة، لا يتأتى معها للموكل أن يقوم بإبرام عقد الزواج بنفسه؛ 2 - تحرير وكالة عقد الزواج في ورقة رسمية أو عرفية، مصادق على توقيع»؟', '["المادة 16", "المادة 17", "المادة 18", "المادة 19"]'::jsonb, 1, 'المادة 17 من مدونة الأسرة تنص على: «يتم عقد الزواج بحضور أطرافه، غير أنه يمكن التوكيل على إبرامه، بإذن من قاضي الأسرة، المكلف بالزواج وفق الشروط الآتية: 1 - وجود ظروف خاصة، لا يتأتى معها للموكل أن يقوم بإبرام عقد الزواج بنفسه؛ 2 - تحرير وكالة عقد الزواج في ورقة رسمية أو عرفية، مصادق على توقيع الموكل فيها؛ 3- أن يكون الوكيل راشدا متمتعا بكامل أهليته المدنية، وفي حالة توكيله من الولي يجب أن تتوفر فيه شروط الولاية؛ 4- أن يعين الموكل في الوكالة اسم الزوج الآخر ومواصفاته، والمعلومات المتعلقة بهويته، وكل المعلومات التي يرى فائدة في ذكرها؛ 5 - أن تتضمن الوكالة قدر الصداق، وعند الاقتضاء المعجل منه والمؤجل. وللموكل أن يحدد الشروط التي يريد إدراجها في العقد والشروط التي يقبلها من الطرف الآخر؛ 6 - أن يؤشر القاضي المذكور على الوكالة بعد التأكد من توفرها على الشروط المطلوبة.»', 'مدونة الأسرة، المادة 17', true),
  ('mdf-art-018', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «ليس للقاضي أن يتولى بنفسه، تزويج من له الولاية عليه من نفسه ولا من أصوله ولا من فروعه»؟', '["المادة 17", "المادة 18", "المادة 19", "المادة 20"]'::jsonb, 1, 'المادة 18 من مدونة الأسرة تنص على: «ليس للقاضي أن يتولى بنفسه، تزويج من له الولاية عليه من نفسه ولا من أصوله ولا من فروعه. القسم الثاني: الأهلية والولاية والصداق الباب الأول: الأهلية والولاية في الزواج»', 'مدونة الأسرة، المادة 18', true),
  ('mdf-art-019', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «تكتمل أهلية الزواج بإتمام الفتى والفتاة المتمتعين بقواهما العقلية ثمان عشرة سنة شمسية»؟', '["المادة 18", "المادة 19", "المادة 20", "المادة 21"]'::jsonb, 1, 'المادة 19 من مدونة الأسرة تنص على: «تكتمل أهلية الزواج بإتمام الفتى والفتاة المتمتعين بقواهما العقلية ثمان عشرة سنة شمسية.»', 'مدونة الأسرة، المادة 19', true),
  ('mdf-art-020', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «لقاضي الأسرة المكلف بالزواج، أن يأذن بزواج الفتى والفتاة دون سن الأهلية المنصوص عليه في المادة 19 أعلاه، بمقرر معلل يبين فيه المصلحة والأسباب المبررة لذلك، بعد الاستماع لأبوي القاصر أو نائبه الشرعي والاستعانة بخبرة طبية أو إجراء بحث اجتماعي»؟', '["المادة 19", "المادة 20", "المادة 21", "المادة 22"]'::jsonb, 1, 'المادة 20 من مدونة الأسرة تنص على: «لقاضي الأسرة المكلف بالزواج، أن يأذن بزواج الفتى والفتاة دون سن الأهلية المنصوص عليه في المادة 19 أعلاه، بمقرر معلل يبين فيه المصلحة والأسباب المبررة لذلك، بعد الاستماع لأبوي القاصر أو نائبه الشرعي والاستعانة بخبرة طبية أو إجراء بحث اجتماعي. مقرر الاستجابة لطلب الإذن بزواج القاصر غير قابل لأي طعن.»', 'مدونة الأسرة، المادة 20', true),
  ('mdf-art-021', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «زواج القاصر متوقف على موافقة نائبه الشرعي»؟', '["المادة 20", "المادة 21", "المادة 22", "المادة 23"]'::jsonb, 1, 'المادة 21 من مدونة الأسرة تنص على: «زواج القاصر متوقف على موافقة نائبه الشرعي. تتم موافقة النائب الشرعي بتوقيعه مع القاصر على طلب الإذن بالزواج وحضوره إبرام العقد. إذا امتنع النائب الشرعي للقاصر عن الموافقة بت قاضي الأسرة المكلف بالزواج في الموضوع.»', 'مدونة الأسرة، المادة 21', true),
  ('mdf-art-022', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «يكتسب المتزوجان طبقا للمادة 20 أعلاه، الأهلية المدنية في ممارسة حق التقاضي في كل ما يتعلق بآثار عقد الزواج من حقوق والتزامات»؟', '["المادة 21", "المادة 22", "المادة 23", "المادة 24"]'::jsonb, 1, 'المادة 22 من مدونة الأسرة تنص على: «يكتسب المتزوجان طبقا للمادة 20 أعلاه، الأهلية المدنية في ممارسة حق التقاضي في كل ما يتعلق بآثار عقد الزواج من حقوق والتزامات. يمكن للمحكمة بطلب من أحد الزوجين أو نائبه الشرعي، أن تحدد التكاليف المالية للزوج المعني وطريقة أدائها.»', 'مدونة الأسرة، المادة 22', true),
  ('mdf-art-023', 'general', 'family-code-70-03', 'general', 'medium', 'أي مادة من مدونة الأسرة (70.03) تنص على: «يأذن قاضي الأسرة المكلف بالزواج بزواج الشخص المصاب بإعاقة ذهنية ذكرا كان أم أنثى، بعد تقديم تقرير حول حالة الإعاقة من طرف طبيب خبير أو أكثر»؟', '["المادة 22", "المادة 23", "المادة 24", "المادة 25"]'::jsonb, 1, 'المادة 23 من مدونة الأسرة تنص على: «يأذن قاضي الأسرة المكلف بالزواج بزواج الشخص المصاب بإعاقة ذهنية ذكرا كان أم أنثى، بعد تقديم تقرير حول حالة الإعاقة من طرف طبيب خبير أو أكثر. يطلع القاضي الطرف الآخر على التقرير وينص على ذلك في محضر. يجب أن يكون الطرف الآخر راشدا ويرضى صراحة في تعهد رسمي بعقد الزواج مع المصاب بالإعاقة.»', 'مدونة الأسرة، المادة 23', true),
